<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Setting, User, Lock, Document, Files, Key, Plus, Download, Refresh, CopyDocument, Upload, CircleCheck, Search, Delete } from '@element-plus/icons-vue'
import { api, download, query } from '../api'
import { useApp } from '../store'
import { dateTime, fileSize, statusLabels, statusType } from '../utils'
import DataTable from '../components/DataTable.vue'
import BrandMark from '../components/BrandMark.vue'
const desktop=window.ruilianDesktop
const app=useApp(),route=useRoute(),router=useRouter(),tab=ref('license'),busy=ref(false),saving=ref(false)
const menu=computed(()=>[{key:'settings',label:'企业与业务参数',icon:Setting,permission:'system.settings'},{key:'users',label:'用户管理',icon:User,permission:'system.users'},{key:'roles',label:'角色与权限',icon:Lock,permission:'system.users'},{key:'numbering',label:'单据编号',icon:Document,permission:'system.settings'},{key:'audit',label:'操作审计',icon:Files,permission:'system.audit'},{key:'backups',label:'备份恢复',icon:Files,permission:'system.backup'},{key:'license',label:'软件授权',icon:Key,permission:''}].filter(v=>!v.permission||app.can(v.permission)))
const settings=reactive<any>({document_prefixes:{}}),destinations=ref(''),users=ref<any[]>([]),roles=ref<any[]>([]),warehouses=ref<any[]>([]),organizations=ref<any[]>([]),logs=ref<any[]>([]),auditSearch=ref(''),auditPage=ref(1),auditTotal=ref(0),backupData=ref<any>({items:[],jobs:[],data_dir:'',backup_destinations:[]}),code=ref(''),license=ref<any>({}),userOpen=ref(false),roleOpen=ref(false),restoreOpen=ref(false)
const userForm=reactive<any>({}),roleForm=reactive<any>({}),fileInput=ref<HTMLInputElement>(),brandFileInput=ref<HTMLInputElement>()
const labels:Record<string,string>={'base':'基础资料','purchase':'采购','sales':'销售','inventory':'库存','finance':'往来账务','price':'价格','reports':'报表','warnings':'预警','system':'系统','amount':'金额','cost':'成本'}
const actions:Record<string,string>={view:'查看',edit:'新增 / 编辑',approve:'审核 / 红冲',override:'手工改价',ack:'确认',settings:'参数管理',users:'用户与角色',audit:'审计日志',backup:'备份恢复',license:'授权激活'}
function permName(permission:string){const parts=permission.split('.');return (labels[parts[0]]||parts[0])+' · '+(actions[parts[1]]||parts[1])}
async function load(){busy.value=true;try{if(['settings','numbering'].includes(tab.value)){Object.assign(settings,await api('/system/settings'));destinations.value=(settings.backup_destinations||[]).join('\n');if(!settings.document_prefixes)settings.document_prefixes={}}
  else if(tab.value==='users'||tab.value==='roles'){const [u,r]=await Promise.all([api('/system/users'),api('/system/roles')]);users.value=u.items;roles.value=r.items;if(app.can('base.view')){[warehouses.value,organizations.value]=await Promise.all(['warehouse','organization'].map(async k=>(await api('/masters/'+k+'?active=true')).items))}}
  else if(tab.value==='audit'){const r=await api('/system/audit?'+query({page:auditPage.value,search:auditSearch.value}));logs.value=r.items;auditTotal.value=r.total}
  else if(tab.value==='backups'){backupData.value=await api('/system/backups');if(app.can('system.settings')){Object.assign(settings,await api('/system/settings'));destinations.value=(settings.backup_destinations||[]).join('\n')}}
  else if(tab.value==='license'){license.value=await api('/license');app.license=license.value}
}catch{}finally{busy.value=false}}
function initialTab(){const candidate=String(route.query.tab||'');tab.value=menu.value.some(m=>m.key===candidate)?candidate:menu.value[0]?.key||'license'}
watch(()=>route.query.tab,()=>{initialTab();load()});watch(()=>app.tick,()=>{if(['users','roles','audit','backups'].includes(tab.value))load()});onMounted(()=>{initialTab();load()})
function changeTab(key:string){router.replace({path:'/system',query:{tab:key}})}
async function saveSettings(scope='general'){let body:any={};if(scope==='brand'){for(const k of ['app_name','brand_short','brand_logo'])body[k]=settings[k]}else if(scope==='general')for(const k of ['company_name','allow_negative_stock','credit_policy','overdue_policy','low_price_policy','stale_days'])body[k]=settings[k];else if(scope==='backup'){for(const k of ['backup_interval_minutes','backup_daily_keep','backup_weekly_keep','backup_monthly_keep'])body[k]=settings[k];body.backup_destinations=destinations.value.split('\n').map(s=>s.trim()).filter(Boolean)}else body.document_prefixes=Object.fromEntries(Object.entries(settings.document_prefixes).filter(([,v])=>v));saving.value=true;try{await api('/system/settings','PUT',body);await app.refreshMe();ElMessage.success('系统设置已保存');load()}catch{}finally{saving.value=false}}
function editUser(row?:any){Object.assign(userForm,row?{...row,password:'',active:!!row.active}:{id:0,username:'',name:'',password:'',role_id:undefined,organization_id:0,active:true});userOpen.value=true}
async function saveUser(){saving.value=true;try{await api('/system/users'+(userForm.id?'/'+userForm.id:''),userForm.id?'PUT':'POST',userForm);userOpen.value=false;ElMessage.success('用户已保存，修改后的账号需重新登录');load()}catch{}finally{saving.value=false}}
function editRole(row?:any){Object.assign(roleForm,row?JSON.parse(JSON.stringify(row)):{id:0,name:'',permissions:[],warehouse_ids:[],data_scope:'all'});roleOpen.value=true}
async function saveRole(){saving.value=true;try{await api('/system/roles'+(roleForm.id?'/'+roleForm.id:''),roleForm.id?'PUT':'POST',roleForm);roleOpen.value=false;ElMessage.success('角色权限已保存，相关用户需重新登录');load()}catch{}finally{saving.value=false}}
async function backup(){saving.value=true;try{const result=await api('/system/backups','POST');if(result.status==='partial')ElMessage.warning(result.message);else ElMessage.success('备份已完成，完整性与 SHA-256 校验通过');load()}catch{}finally{saving.value=false}}
async function verify(row:any){saving.value=true;try{await api('/system/backups/'+row.id+'/verify','POST');ElMessage.success('恢复验证通过：备份可打开且核心业务表完整');load()}catch{}finally{saving.value=false}}
async function activate(){if(!code.value.trim()){ElMessage.warning('请先输入授权码');return};saving.value=true;try{license.value=await api('/license/activate','POST',{code:code.value.trim()});app.license=license.value;code.value='';ElMessage.success('永久授权已激活');await app.refreshMe()}catch{}finally{saving.value=false}}
async function importBrandLogo(event:Event){
  const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return
  if(!['image/png','image/jpeg'].includes(file.type)||file.size>512*1024){ElMessage.warning('请选择不超过 512 KB 的 PNG 或 JPEG 图片');return}
  try{const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)});const image=new Image();image.src=data;await image.decode();if(image.width<16||image.height<16||image.width>1024||image.height>1024){ElMessage.warning('Logo 宽高均须为 16～1024 像素');return};settings.brand_logo=data;ElMessage.success('Logo 已读取，请保存品牌设置')}catch{ElMessage.warning('图片无法读取，请重新选择')}
}
async function importLicense(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;if(file.size>20000){ElMessage.warning('授权文件不能超过 20 KB');input.value='';return};code.value=(await file.text()).trim();input.value='';ElMessage.success('授权文件已读取，请点击激活授权')}
async function copy(text:string){try{await navigator.clipboard.writeText(text);ElMessage.success('已复制')}catch{ElMessage.warning('无法自动复制，请选中文本手动复制')}}
const latestBackup=computed(()=>backupData.value.items.find((b:any)=>['ok','partial'].includes(b.status)))
const fullControl=computed({get:()=>roleForm.permissions?.includes('*'),set:(v:boolean)=>roleForm.permissions=v?['*']:[]})
const builtInAdmin=computed(()=>roleForm.built_in&&roleForm.permissions?.includes('*'))
</script>
<template>
  <div class="page-head"><div><h1>系统管理</h1><p>管理企业参数、访问权限与数据备份，让系统可靠地支撑日常经营。</p></div></div>
  <div class="system-layout"><aside class="panel system-menu"><button v-for="item in menu" :key="item.key" :class="{selected:tab===item.key}" @click="changeTab(item.key)"><el-icon><component :is="item.icon"/></el-icon>{{item.label}}</button></aside><section class="panel" v-loading="busy">
    <div class="panel-head"><div><h3>{{menu.find(m=>m.key===tab)?.label}}</h3><p>{{tab==='license'?'离线试用与永久授权，授权失效不会删除经营数据':tab==='backups'?'一致性快照、完整性校验与恢复验证':tab==='audit'?'登录、资料变更、审核、核销与恢复操作的完整轨迹':'所有修改均保留操作审计'}}</p></div><el-button v-if="tab==='users'" type="primary" :icon="Plus" @click="editUser()">新增用户</el-button><el-button v-if="tab==='roles'" type="primary" :icon="Plus" @click="editRole()">新增角色</el-button><el-button v-if="tab==='backups'" type="primary" :loading="saving" @click="backup">立即备份</el-button><el-button v-if="tab==='license'" :icon="Refresh" @click="load">重新检查</el-button></div>
    <div v-if="tab==='settings'" class="panel-body">
      <el-form class="settings-form brand-settings" label-position="top"><h3 class="section-title">软件名称与 Logo</h3><div class="form-grid two">
        <el-form-item class="wide" label="软件名称"><el-input v-model="settings.app_name" maxlength="64" show-word-limit placeholder="显示在登录页、窗口标题和授权页"/></el-form-item>
        <el-form-item label="品牌简称"><el-input v-model="settings.brand_short" maxlength="12" show-word-limit placeholder="显示在侧边导航"/></el-form-item>
        <el-form-item class="wide" label="软件 Logo"><div class="logo-editor"><BrandMark :logo="settings.brand_logo || ''"/><div><div class="flex gap8"><el-button :icon="Upload" @click="brandFileInput?.click()">上传 Logo</el-button><el-button :disabled="!settings.brand_logo" @click="settings.brand_logo=''">恢复默认图标</el-button></div><p class="muted">PNG / JPEG，最多 512 KB，宽高 16～1024 像素。</p></div><input ref="brandFileInput" type="file" accept="image/png,image/jpeg" style="display:none" @change="importBrandLogo"/></div></el-form-item>
      </div><p class="muted mb16">请使用您有权使用的名称与 Logo。保存后立即更新界面，并随数据库备份保留。</p><el-button type="primary" :loading="saving" @click="saveSettings('brand')">保存品牌设置</el-button><p class="muted mt16">内置字体 Noto Sans SC：OFL 1.1；界面图标 Element Plus Icons：MIT。许可证随安装包附带。</p></el-form>
      <h3 class="section-title">企业与业务参数</h3><el-form class="settings-form" label-position="top"><div class="form-grid two"><el-form-item class="wide" label="企业名称"><el-input v-model="settings.company_name" maxlength="80"/></el-form-item><el-form-item label="记账币种"><el-input model-value="人民币 CNY" disabled/></el-form-item><el-form-item label="呆滞库存阈值（天）"><el-input-number v-model="settings.stale_days" :min="1" :max="3650" :precision="0" controls-position="right"/></el-form-item><el-form-item label="客户信用超额"><el-select v-model="settings.credit_policy"><el-option label="禁止审核销售业务" value="block"/><el-option label="预警提醒，允许审核" value="warn"/></el-select></el-form-item><el-form-item label="客户应收逾期"><el-select v-model="settings.overdue_policy"><el-option label="预警提醒，允许审核" value="warn"/><el-option label="禁止审核销售业务" value="block"/></el-select></el-form-item><el-form-item label="低于最低售价"><el-select v-model="settings.low_price_policy"><el-option label="禁止审核" value="block"/><el-option label="仅预警提醒" value="warn"/></el-select></el-form-item><el-form-item label="负库存策略"><el-switch v-model="settings.allow_negative_stock" active-text="允许负库存" inactive-text="禁止"/></el-form-item><div v-if="settings.allow_negative_stock" class="hint-box wide mb16">负库存按现有平均成本或商品参考采购价暂估，后续回补差异形成独立成本调整。序列号商品与订单占用库存始终禁止透支。</div></div><el-button type="primary" :loading="saving" @click="saveSettings()">保存业务参数</el-button></el-form></div>
    <div v-if="tab==='numbering'" class="panel-body"><div class="hint-box mb24">编号格式：前缀-业务日期-当日流水，例如 CGRK-20260914-0001。编号在事务中生成，留空使用内置前缀。更改前缀不影响已有单号。</div><el-form label-position="top"><div class="form-grid two"><el-form-item v-for="k in app.kinds" :key="k.key" :label="k.name"><el-input v-model="settings.document_prefixes[k.key]" maxlength="16" placeholder="使用内置前缀"/></el-form-item></div><el-button type="primary" :loading="saving" @click="saveSettings('numbering')">保存编号规则</el-button></el-form></div>
    <DataTable v-if="tab==='users'" :rows="users" :columns="[{key:'username',label:'用户名',minWidth:140},{key:'name',label:'姓名',minWidth:130},{key:'role_name',label:'所属角色',minWidth:145},{key:'active',label:'状态',type:'boolean',width:85},{key:'created_at',label:'创建时间',type:'datetime',minWidth:170}]"><template #actions="{row}"><el-button link type="primary" @click="editUser(row)">编辑</el-button></template></DataTable>
    <DataTable v-if="tab==='roles'" :rows="roles.map(r=>({...r,permission_count:r.permissions.includes('*')?'完全控制':r.permissions.length+' 项权限',scope_label:r.data_scope==='own'?'仅本人业务':'全部业务',warehouses_label:r.warehouse_ids.length?'限定 '+r.warehouse_ids.length+' 个仓库':'全部仓库'}))" :columns="[{key:'name',label:'角色名称',minWidth:170},{key:'permission_count',label:'功能权限',minWidth:120},{key:'scope_label',label:'数据范围',minWidth:120},{key:'warehouses_label',label:'仓库范围',minWidth:130}]"><template #actions="{row}"><el-button link type="primary" :disabled="row.built_in&&row.permissions.includes('*')" @click="editRole(row)">配置权限</el-button></template></DataTable>
    <template v-if="tab==='audit'"><div class="filter-row"><el-input v-model="auditSearch" :prefix-icon="Search" placeholder="用户、操作或单据编号" clearable @keyup.enter="auditPage=1;load()"/><el-button type="primary" plain @click="auditPage=1;load()">查询</el-button></div><el-table :data="logs"><el-table-column prop="username" label="操作用户" width="110"/><el-table-column prop="action" label="操作" min-width="145"/><el-table-column prop="ip" label="来源 IP" min-width="130"/><el-table-column label="时间" min-width="180"><template #default="{row}">{{dateTime(row.created_at)}}</template></el-table-column><el-table-column label="变更摘要" width="110"><template #default="{row}"><el-popover trigger="click" width="600" placement="left"><template #reference><el-button link type="primary">查看详情</el-button></template><pre class="audit-detail">{{JSON.stringify({变更前:row.before_data,变更后:row.after_data},null,2)}}</pre></el-popover></template></el-table-column></el-table><div class="table-footer"><span class="muted">共 {{auditTotal}} 条审计记录</span><el-pagination v-model:current-page="auditPage" :total="auditTotal" :page-size="50" layout="prev,pager,next" background @current-change="load"/></div></template>
    <template v-if="tab==='backups'"><div class="panel-body"><div class="hint-box mb16"><b>数据目录</b><p class="backup-path">{{backupData.data_dir}}</p><p>最近成功备份：{{latestBackup?dateTime(latestBackup.created_at):'尚未备份'}} · 自动快照间隔 {{backupData.interval_minutes||15}} 分钟</p></div><el-alert v-if="backupData.backup_destinations.length<2" type="warning" show-icon :closable="false" title="请配置独立介质与异地副本" description="当前本地备份不能覆盖整盘故障。建议配置独立磁盘 / 备份服务器及异地目录各一处，形成至少三份副本。" class="mb16"/><div class="flex gap8"><el-button v-if="desktop" type="primary" plain @click="desktop.restore()">从备份恢复</el-button><el-button v-if="desktop" @click="desktop.openDataDirectory()">打开数据目录</el-button><el-button :icon="Download" @click="restoreOpen=true">查看恢复步骤</el-button><el-button :icon="Refresh" @click="load">刷新备份列表</el-button></div></div>
      <el-table :data="backupData.items.slice(0,40)"><template #empty><el-empty description="尚无备份，点击立即备份生成第一份副本" :image-size="70"/></template><el-table-column label="备份文件" min-width="240"><template #default="{row}"><span style="font-size:11px">{{row.filename}}</span><small class="muted" style="display:block;font-size:10px">{{fileSize(row.size)}} · {{dateTime(row.created_at)}}</small></template></el-table-column><el-table-column label="状态" width="95"><template #default="{row}"><el-tooltip :content="row.message"><el-tag :type="statusType(row.status)" size="small">{{row.status==='expired'?'已清理':statusLabels[row.status]||row.status}}</el-tag></el-tooltip></template></el-table-column><el-table-column label="校验" width="85"><template #default="{row}"><el-tag :type="row.integrity==='ok'?'success':'danger'" size="small">{{row.integrity==='ok'?'通过':'失败'}}</el-tag></template></el-table-column><el-table-column label="副本" width="100"><template #default="{row}"><el-popover trigger="hover" width="390"><template #reference><el-button link type="primary">{{row.replicas.filter((r:any)=>r.status==='ok').length}} 份</el-button></template><p v-if="!row.replicas.length" class="muted">未配置独立备份目录</p><div v-for="replica in row.replicas" :key="replica.path" class="mb16"><p class="backup-path">{{replica.path}}</p><el-tag :type="replica.status==='ok'?'success':'danger'" size="small">{{replica.status==='ok'?'校验通过':'失败 · 已重试 '+replica.attempts+' 次'}}</el-tag><p class="muted">{{replica.message}}</p></div></el-popover></template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="row.status==='expired'||saving" @click="verify(row)">验证</el-button><el-button link type="primary" :disabled="row.status==='expired'" @click="download('/system/backups/'+row.id+'/download',row.filename)">下载</el-button></template></el-table-column></el-table>
      <div v-if="app.can('system.settings')" class="panel-body"><h3 class="section-title">自动备份与保留策略</h3><el-form label-position="top"><div class="form-grid two"><el-form-item label="自动快照间隔（分钟）"><el-input-number v-model="settings.backup_interval_minutes" :min="1" :max="1440" :precision="0" controls-position="right"/></el-form-item><el-form-item label="每日备份保留份数"><el-input-number v-model="settings.backup_daily_keep" :min="1" :max="3650" :precision="0" controls-position="right"/></el-form-item><el-form-item label="每周备份保留份数"><el-input-number v-model="settings.backup_weekly_keep" :min="1" :max="3650" :precision="0" controls-position="right"/></el-form-item><el-form-item label="每月备份保留份数"><el-input-number v-model="settings.backup_monthly_keep" :min="1" :max="3650" :precision="0" controls-position="right"/></el-form-item><el-form-item class="wide" label="独立磁盘 / 异地备份目录（每行一个绝对路径，最多三处）"><el-input v-model="destinations" type="textarea" :rows="3" placeholder="例如：E:\业务备份&#10;\\备份服务器\企业数据\业务备份"/></el-form-item></div><p class="muted mb16">应用运行期间执行自动任务；快照保留最近 192 份，手动备份不自动清理。异盘副本由对应介质的保留策略管理。</p><el-button type="primary" :loading="saving" @click="saveSettings('backup')">保存备份策略</el-button></el-form><div v-if="backupData.jobs.some((j:any)=>j.status==='dead_letter')" class="mt16"><el-alert type="error" title="存在重试三次后仍失败的自动备份任务，请检查日志与磁盘目录。" :closable="false"/></div></div>
    </template>
    <div v-if="tab==='license'" class="panel-body"><div class="license-card"><BrandMark/><div><h2>{{app.branding.app_name}}</h2><p>V1.1.0 · {{license.status==='active'?'离线永久授权':'10 天完整功能试用'}}</p></div><div class="spacer"></div><el-tag :type="statusType(license.status)" size="large">{{statusLabels[license.status]||'检查中'}}</el-tag></div><el-alert v-if="license.message" :title="license.message" :type="license.status==='active'?'success':license.status==='trial'?'info':'warning'" :closable="false" show-icon class="mb24"/><h3 class="section-title">本机安装标识</h3><div class="license-installation"><code>{{license.installation_id}}</code><el-button size="small" :icon="CopyDocument" @click="copy(license.installation_id)">复制</el-button></div><p class="muted mt16">将 Installation ID 提供给软件发行方，即可获取绑定本机的授权码。</p><el-descriptions :column="2" border class="mt16"><el-descriptions-item label="首次运行">{{dateTime(license.first_run)}}</el-descriptions-item><el-descriptions-item label="试用结束">{{dateTime(license.trial_end)}}</el-descriptions-item><el-descriptions-item label="授权类型">{{license.license?'永久授权 PERPETUAL':'试用授权'}}</el-descriptions-item><el-descriptions-item label="剩余试用">{{license.status==='active'?'已永久激活':license.days_remaining+' 天'}}</el-descriptions-item><el-descriptions-item v-if="license.license" label="授权编号" :span="2">{{license.license.license_id}}</el-descriptions-item><el-descriptions-item v-if="license.license" label="客户编号">{{license.license.customer_id}}</el-descriptions-item><el-descriptions-item v-if="license.license" label="激活时间">{{dateTime(license.activated_at)}}</el-descriptions-item><el-descriptions-item v-if="license.license" label="版本范围">{{license.license.version_from}} ～ {{license.license.version_to}}</el-descriptions-item><el-descriptions-item v-if="license.license" label="授权功能">{{license.license.features.includes('*')?'全部业务功能':license.license.features.map((f:string)=>labels[f]||f).join('、')}}</el-descriptions-item></el-descriptions><template v-if="app.can('system.license')"><h3 class="section-title">输入正式授权码</h3><el-input v-model="code" type="textarea" :rows="5" placeholder="粘贴发行方提供的完整授权码，或导入 .license 文件" maxlength="20000"/><div class="flex gap8 mt16"><el-button type="primary" :loading="saving" :disabled="!code.trim()" @click="activate">激活永久授权</el-button><el-button :icon="Upload" @click="fileInput?.click()">导入授权文件</el-button><input ref="fileInput" type="file" accept=".license,.txt" style="display:none" @change="importLicense"/></div></template><p class="muted mt16">授权与业务数据独立保护。试用到期或授权异常时，仍可登录、查看、导出与备份；更换服务器后请重新绑定安装标识。</p></div>
  </section></div>
  <el-dialog v-model="userOpen" :title="userForm.id?'编辑用户':'新增用户'" width="560px"><el-form label-position="top"><div class="form-grid two"><el-form-item label="用户名 *"><el-input v-model="userForm.username" autocomplete="off"/></el-form-item><el-form-item label="姓名 *"><el-input v-model="userForm.name"/></el-form-item><el-form-item class="wide" :label="userForm.id?'新密码（留空不变）':'密码 *'"><el-input v-model="userForm.password" type="password" show-password autocomplete="new-password" placeholder="至少 8 位，包含数字与非数字字符"/></el-form-item><el-form-item label="角色 *"><el-select v-model="userForm.role_id"><el-option v-for="r in roles" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item><el-form-item label="所属组织"><el-select v-model="userForm.organization_id"><el-option label="未指定" :value="0"/><el-option v-for="r in organizations" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item><el-form-item label="账号状态"><el-switch v-model="userForm.active" active-text="启用" inactive-text="停用"/></el-form-item></div></el-form><template #footer><el-button @click="userOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveUser">保存用户</el-button></template></el-dialog>
  <el-drawer v-model="roleOpen" :title="roleForm.id?'编辑角色权限':'新增角色'" size="760px"><el-form label-position="top" :disabled="!!builtInAdmin"><el-form-item label="角色名称 *"><el-input v-model="roleForm.name"/></el-form-item><div class="form-grid two"><el-form-item label="业务数据范围"><el-select v-model="roleForm.data_scope"><el-option label="全部业务数据" value="all"/><el-option label="仅本人创建的业务" value="own"/></el-select></el-form-item><el-form-item label="可访问仓库（留空为全部）"><el-select v-model="roleForm.warehouse_ids" multiple filterable collapse-tags><el-option v-for="w in warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item></div><el-form-item><el-checkbox v-model="fullControl">系统管理员完全控制</el-checkbox></el-form-item><el-checkbox-group v-if="!fullControl" v-model="roleForm.permissions"><div class="permission-grid"><div v-for="(permissions,group) in app.permissionGroups" :key="group" class="permission-group"><strong>{{group}}</strong><el-checkbox v-for="permission in permissions" :key="permission" :value="permission">{{permName(permission)}}</el-checkbox></div></div></el-checkbox-group><p class="muted mt16">“金额查看”与“成本查看”独立控制展示和导出。仓库限制应用于单据、库存、往来和报表。</p></el-form><template #footer><el-button @click="roleOpen=false">取消</el-button><el-button type="primary" :disabled="!!builtInAdmin" :loading="saving" @click="saveRole">保存权限</el-button></template></el-drawer>
  <el-dialog v-model="restoreOpen" title="数据库恢复步骤" width="700px"><div class="help-content"><ol v-if="desktop"><li>先找到需要恢复的 SQLite 备份，保存好当前正在编辑的单据。</li><li>点击“从备份恢复”，选择备份文件并确认目标数据目录。</li><li>客户端会验证备份、自动停止数据服务、保存恢复前副本并恢复数据库。</li><li>恢复完成后客户端自动重新打开，请核对库存、往来和授权状态。</li></ol><ol v-else><li>先验证目标备份，再停止本机服务。</li><li>使用下方命令执行恢复。恢复前会保存当前数据库及 WAL 文件的副本。</li><li>重新启动后核对库存、往来和授权状态。</li></ol><pre v-if="!desktop" class="restore-command">.\数据服务.exe --data-dir "{{backupData.data_dir}}" --restore "备份文件的完整路径"</pre><el-alert title="恢复前副本会保留在 data\pre-restore-日期时间 目录" type="info" :closable="false" description="请保留该目录直到业务数据核对完成。更换机器时授权需要由发行方重新绑定，恢复不会删除经营数据。"/></div><template #footer><el-button @click="restoreOpen=false">知道了</el-button></template></el-dialog>
</template>
<style scoped>.brand-settings{padding-bottom:26px;border-bottom:1px solid #e7edf5}.logo-editor{display:flex;align-items:center;gap:18px}.logo-editor>.brand-mark{width:66px;height:66px;object-fit:contain;background:#f4f7fb;border:1px solid #e2eaf4}.logo-editor p{margin:9px 0 0;font-size:11px}.audit-detail{white-space:pre-wrap;word-break:break-all;font-size:11px;max-height:420px;overflow:auto;color:#637997;margin:0;line-height:1.7}.restore-command{background:#f4f7fb;border:1px solid #e2eaf4;border-radius:7px;padding:16px;white-space:pre-wrap;word-break:break-all;font-size:11px;line-height:1.9;color:#637997}.el-descriptions{font-size:12px}</style>
